'use client';
import React from 'react';

import EmojiPicker from 'emoji-picker-react';

// Reactions float in a translucent dark pill above the call controls;
// "+" expands to a dark full picker.
export type PickerExampleProps = {
  /** The picker root: EmojiPicker, or a styled() wrapper of it. */
  Root?: React.ComponentType<Omit<React.ComponentProps<typeof EmojiPicker>, 'theme'>>;
  className?: string;
};

export function PickerExample({
  Root: RootComponent = EmojiPicker,
  className,
}: PickerExampleProps) {
  return (
    <RootComponent
      className={className}
      colorScheme="dark"
      reactionsDefaultOpen
      reactions={['1f44f', '1f44d', '2764-fe0f', '1f602', '1f62e', '1f389']}
      width={360}
      height={380}
    />
  );
}

/* Video call reactions — a translucent dark pill floating over video;
   the expanded picker keeps the dark color scheme. */
.call-picker {
  --epr-reactions-bg-color: rgb(32 33 36 / 82%);
  --epr-picker-border-color: rgb(255 255 255 / 14%);
  --epr-hover-bg-color-reduced-opacity: rgb(255 255 255 / 16%);
  --epr-emoji-size: 32px;
  box-shadow: 0 12px 30px rgb(0 0 0 / 45%);
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}
.call-picker [data-epr-part='reactions'] {
  gap: 2px;
  padding: 0 8px;
}
.call-picker [data-epr-part='expand-reactions'] {
  background-color: rgb(255 255 255 / 12%);
}

